package com.yuegang.zhihui.system.application;
import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.system.api.*;import com.yuegang.zhihui.system.domain.*;
public final class AuthorizationService{private final AuthorizationRepository repository;public AuthorizationService(AuthorizationRepository r){repository=r;}public AuthoritySnapshot snapshot(String user){return repository.snapshot(id(user));}public AuthoritySnapshot assign(String user,AssignRolesRequest r,long operator){if(r.reason()!=null&&r.reason().length()>500)throw new BusinessException(ErrorCode.VALIDATION_ERROR);return repository.replaceRoles(id(user),r.version(),r.roleCodes(),operator,r.reason()).orElseThrow(()->new BusinessException(ErrorCode.BUSINESS_CONFLICT));}private static long id(String s){try{long v=Long.parseLong(s);if(v<=0)throw new NumberFormatException();return v;}catch(NumberFormatException e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}}
